-- V1 (report-service T2; spec docs/specs/report-service.md D14, ERD group report_service): the phase-1 schema.
-- Database pattern for every service: ids are uuid generated by the application; timestamps are timestamptz set by
-- the application from the service clock (no database defaults); enums are varchar(32) with a CHECK listing the Java
-- constants (ERD-D12); JSON is jsonb; every foreign-key column leads an index. Phase 1 deletes nothing, so every
-- foreign key is named fk_<table>_<column> and restricts deletes. The ERD's attachments table is not created in phase 1
-- (spec D1, D9). Ids of other services' rows (projects, users, features, scenarios, example rows, steps) are plain
-- uuid columns without a foreign key.

-- Where a run executed (D11): matched by exact, case-sensitive name, created on first use.
CREATE TABLE environments (
    id          uuid                     NOT NULL,
    project_id  uuid                     NOT NULL,
    name        varchar(100)             NOT NULL,
    description text,
    created_at  timestamp with time zone NOT NULL,
    updated_at  timestamp with time zone NOT NULL,
    CONSTRAINT pk_environments PRIMARY KEY (id),
    CONSTRAINT uk_environments_project_id_name UNIQUE (project_id, name)
);

-- The build under test (D11): matched by exact name; branch, commit and CI URL come from the first run that names it.
CREATE TABLE builds (
    id         uuid                     NOT NULL,
    project_id uuid                     NOT NULL,
    name       varchar(255)             NOT NULL,
    branch     varchar(255),
    commit_sha varchar(64),
    ci_url     varchar(2048),
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_builds PRIMARY KEY (id),
    CONSTRAINT uk_builds_project_id_name UNIQUE (project_id, name)
);

-- CI upload tokens (D4): only the SHA-256 hex of the token is stored; the token text never is.
CREATE TABLE upload_tokens (
    id           uuid                     NOT NULL,
    project_id   uuid                     NOT NULL,
    name         varchar(100)             NOT NULL,
    token_hash   char(64)                 NOT NULL,
    token_prefix varchar(16)              NOT NULL,
    created_by   uuid                     NOT NULL,
    expires_at   timestamp with time zone,
    last_used_at timestamp with time zone,
    revoked_at   timestamp with time zone,
    revoked_by   uuid,
    created_at   timestamp with time zone NOT NULL,
    updated_at   timestamp with time zone NOT NULL,
    CONSTRAINT pk_upload_tokens PRIMARY KEY (id),
    CONSTRAINT uk_upload_tokens_token_hash UNIQUE (token_hash)
);

CREATE INDEX ix_upload_tokens_project_id ON upload_tokens (project_id);

-- One execution of a set of test cases (D8): MANUAL runs are planned by people, AUTOMATED runs come from a CI upload.
CREATE TABLE test_runs (
    id              uuid                     NOT NULL,
    project_id      uuid                     NOT NULL,
    name            varchar(255)             NOT NULL,
    source          varchar(32)              NOT NULL,
    status          varchar(32)              NOT NULL,
    environment_id  uuid,
    build_id        uuid,
    tag_expression  varchar(1000),
    upload_token_id uuid,
    created_by      uuid,
    started_at      timestamp with time zone,
    finished_at     timestamp with time zone,
    created_at      timestamp with time zone NOT NULL,
    updated_at      timestamp with time zone NOT NULL,
    CONSTRAINT pk_test_runs PRIMARY KEY (id),
    CONSTRAINT ck_test_runs_source_values CHECK (source IN ('MANUAL', 'AUTOMATED')),
    CONSTRAINT ck_test_runs_status_values CHECK (status IN ('PLANNED', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED')),
    CONSTRAINT fk_test_runs_environment_id FOREIGN KEY (environment_id) REFERENCES environments (id)
        ON DELETE RESTRICT,
    CONSTRAINT fk_test_runs_build_id FOREIGN KEY (build_id) REFERENCES builds (id) ON DELETE RESTRICT,
    CONSTRAINT fk_test_runs_upload_token_id FOREIGN KEY (upload_token_id) REFERENCES upload_tokens (id)
        ON DELETE RESTRICT
);

-- The run list, newest first (D12).
CREATE INDEX ix_test_runs_project_id_created_at ON test_runs (project_id, created_at);
CREATE INDEX ix_test_runs_environment_id ON test_runs (environment_id);
CREATE INDEX ix_test_runs_build_id ON test_runs (build_id);
CREATE INDEX ix_test_runs_upload_token_id ON test_runs (upload_token_id);

-- The result of one test case in one run (D6): a snapshot, so history survives edits in scenario-service.
CREATE TABLE test_case_results (
    id              uuid                     NOT NULL,
    test_run_id     uuid                     NOT NULL,
    position        integer                  NOT NULL,
    feature_id      uuid,
    feature_version integer,
    scenario_id     uuid,
    example_row_id  uuid,
    feature_path    text                     NOT NULL,
    feature_name    text                     NOT NULL,
    scenario_name   text                     NOT NULL,
    tags            jsonb                    NOT NULL,
    line            integer,
    status          varchar(32)              NOT NULL,
    attempt         integer                  NOT NULL,
    executed_by     uuid,
    comment         text,
    started_at      timestamp with time zone,
    finished_at     timestamp with time zone,
    duration_ms     bigint,
    created_at      timestamp with time zone NOT NULL,
    updated_at      timestamp with time zone NOT NULL,
    CONSTRAINT pk_test_case_results PRIMARY KEY (id),
    CONSTRAINT uk_test_case_results_test_run_id_position UNIQUE (test_run_id, position),
    CONSTRAINT ck_test_case_results_status_values CHECK (status IN ('PASSED', 'FAILED', 'SKIPPED', 'PENDING',
        'UNDEFINED', 'AMBIGUOUS', 'UNKNOWN')),
    CONSTRAINT fk_test_case_results_test_run_id FOREIGN KEY (test_run_id) REFERENCES test_runs (id)
        ON DELETE RESTRICT
);

-- For the later "latest result per scenario".
CREATE INDEX ix_test_case_results_scenario_id ON test_case_results (scenario_id);

-- Steps and hooks of a test case result, in execution order (D9, D10).
CREATE TABLE step_results (
    id                  uuid                     NOT NULL,
    test_case_result_id uuid                     NOT NULL,
    position            integer                  NOT NULL,
    kind                varchar(32)              NOT NULL,
    step_id             uuid,
    keyword_text        text,
    step_text           text,
    data_table          jsonb,
    doc_string          text,
    status              varchar(32)              NOT NULL,
    duration_ms         bigint,
    error_message       text,
    created_at          timestamp with time zone NOT NULL,
    updated_at          timestamp with time zone NOT NULL,
    CONSTRAINT pk_step_results PRIMARY KEY (id),
    CONSTRAINT uk_step_results_test_case_result_id_position UNIQUE (test_case_result_id, position),
    CONSTRAINT ck_step_results_kind_values CHECK (kind IN ('STEP', 'BEFORE_HOOK', 'AFTER_HOOK')),
    CONSTRAINT ck_step_results_status_values CHECK (status IN ('PASSED', 'FAILED', 'SKIPPED', 'PENDING', 'UNDEFINED',
        'AMBIGUOUS', 'UNKNOWN')),
    CONSTRAINT fk_step_results_test_case_result_id FOREIGN KEY (test_case_result_id)
        REFERENCES test_case_results (id) ON DELETE RESTRICT
);
